&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;br /&gt;&lt;br /&gt;Voici la page de travail de l&#39;int&#233;gration du manuel Armes et &#233;quipement.&lt;br /&gt;&lt;br /&gt;
&lt;h1 class=&quot;separator&quot;&gt;ARMES ET ARMURES 6&lt;a class=&quot;headeranchor&quot; id=&quot;ARMES_ET_ARMURES_G_0&quot; href=&quot;#ARMES_ET_ARMURES_G_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h1&gt;&lt;ul&gt;&lt;li&gt;&lt;strike&gt;Armures 8 -&gt; description individuelle des armures (rectulo) + tableau r&#233;capitulatif des armures (Styx et rectulo)&lt;/strike&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;Armes 16 &lt;i&gt;en cours&lt;/i&gt; avec red&#233;coupage des pages pour coller davantage avec la pr&#233;sentation des armures. (rectulo)&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;Le tableur a &#233;t&#233; rempli avec toutes les armes sur la googlesheet (rectulo). Il reste &#224; exporter vers le wiki &#224; partir d&#39;un programme automatique (styx).&lt;br /&gt;&lt;br /&gt;Il faudra aussi retraiter les &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Et-Armures-Primitives.html&quot; title=&quot;Armes et armures primitives&quot;&gt;Armes et armures primitives&lt;/a&gt;,&lt;br /&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;munitions&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;Armes &#224; feu 41 -&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armes-&#192;-Feu.html&quot; title=&quot;Tableau r&#233;capitulatif des armes &#224; feu&quot;&gt;Tableau r&#233;capitulatif des armes &#224; feu&lt;/a&gt;, &lt;a class=&quot;unknownlink&quot; href=&quot;Description-Des-Armes-&#192;-Feu.html&quot; title=&quot;Pathfinder-RPG.Description des armes &#224; feu&quot;&gt;Description des armes &#224; feu&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;Les armes &#224; feu&lt;/a&gt; cr&#233;&#233;es. /!\ Il faut faciliter la navigation vers et entre ces pages.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;Groupes d’armes du guerrier 47 -&gt; page &lt;a class=&quot;pagelink&quot; href=&quot;Groupe-Darmes.html&quot; title=&quot;Les groupes d&amp;#39;arme du guerrier&quot;&gt;groupe darmes&lt;/a&gt; cr&#233;&#233;e, texte copi&#233; avec un d&#233;but de mise en forme, reste &#224; faire les liens vers les armes en utilisant le format [[descriptions individuelles des armes#Nomdelarme|Nom de l&#39;arme]] (rectulo). (&lt;a class=&quot;unknownlink&quot; href=&quot;Temp-Groupes-Darmes.html&quot; title=&quot;Pathfinder-RPG.Temp-Groupes darmes&quot;&gt;Temp-Groupes d&#39;armes&lt;/a&gt; rempli, plus qu&#39;&#224; faire les redirections des armes)&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;Mat&#233;riaux sp&#233;ciaux 48 -&gt; int&#233;gration achev&#233;e (rectulo). Y int&#233;grer les &lt;a class=&quot;unknownlink&quot; href=&quot;Temp---Mat&#233;riaux-Primaires.html&quot; title=&quot;Pathfinder-RPG.Temp - Mat&#233;riaux primaires&quot;&gt;mat&#233;riaux primaires&lt;/a&gt; ?&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
